// scene3d/diag/combat.js — CombatManeuverTable lookup observability
//
// Observes the CMT lookup pipeline (`ui/ac_combat_maneuver.js`) — load
// lifecycle, hit/miss rates per (stance, attackHeight, attackType)
// tuple, and which motion u32s the dispatch resolves to. Useful for
// confirming the placeholder `setSwingPose` vibe-pose path is no
// longer firing and that real motions come back from the table.
//
// Hooks fire from `ui/ac_combat_maneuver.js` at success/fail of
// loadCombatManeuverTable + hit/miss inside getCombatManeuver.

import { getCombatDiagSnapshot } from "../../ui/ac_combat_maneuver.js";

const DEFAULT_MAX_FAILURES = 20;
const DEFAULT_MAX_MISSES = 100;
const DEFAULT_MAX_HITS_SAMPLE = 50;
// Plugin-client poll give-up ceiling: 60 ticks @ 500ms ≈ 30s. Stops the
// subscription-install polls from spinning forever when the page is
// opened without ever logging in (no `window.__pluginClient`).
const SUB_POLL_MAX_TICKS = 60;
// Wave 12 / Phase 39 (2026-05-26): sneak-attack predictor accuracy.
// Window inside which a `damageDealt` event with `attackConditions`
// SneakAttack bit (0x4) can be retroactively matched to a recent
// `sneakAttackPredicted` emission. 2000ms covers melee swing-windup +
// flight-of-fist + ACE's combat-tick processing under typical RTT;
// can be tuned via the public `setSneakMatchWindowMs` setter.
const DEFAULT_SNEAK_MATCH_WINDOW_MS = 2000;
// Bit 0x4 of `AttackConditions` (ACE.Entity/Enum/AttackConditions.cs:11)
// is set when DamageEvent.SneakAttackMod > 1.0f
// (ACE.Server/Entity/DamageEvent.cs:693-694) — i.e. when a real
// server-side sneak attack happened. Surfaced to JS unchanged in
// `src/lib.rs:23601` (`attackConditions: data.attack_conditions.bits()`).
const ATTACK_CONDITIONS_BIT_SNEAK_ATTACK = 0x4;

// Lazy fetch + cache of the MotionCommand u32 → name table generated by
// `scripts/gen-motion-command-names.cjs`. Used only to humanize the
// motion-u32 histogram in snapshot() output. Failures are non-fatal — if
// the fetch errors the diag falls back to raw hex.
let _motionNamesPromise = null;
let _motionNames = null;
function _ensureMotionNamesLoaded() {
  if (_motionNamesPromise) return _motionNamesPromise;
  _motionNamesPromise = fetch("./data/motion-command-names.json", { cache: "force-cache" })
    .then((r) => r.ok ? r.json() : null)
    .then((j) => { _motionNames = j || null; return _motionNames; })
    .catch(() => { _motionNames = null; return null; });
  return _motionNamesPromise;
}

function errStr(e) {
  if (e == null) return "(null)";
  if (typeof e === "string") return e;
  if (e.message) return String(e.message);
  try { return String(e); } catch (_) { return "(unstringifiable)"; }
}

function hexId(d) { return "0x" + ((d >>> 0).toString(16).padStart(8, "0")); }

function motionName(u32) {
  if (!_motionNames) return null;
  return _motionNames[hexId(u32)] ?? null;
}

function pushCapped(arr, entry, max) {
  arr.push(entry);
  if (arr.length > max) arr.shift();
}

// Convert Map<u32, count> → plain object keyed by hex string + joined
// against the motion-name table. Sorted by descending count for
// readability.
function _motionMapToObj(m) {
  const entries = [];
  for (const [u32, count] of m.entries()) {
    entries.push({ motion: u32 >>> 0, motionName: motionName(u32), count });
  }
  entries.sort((a, b) => b.count - a.count);
  const out = {};
  for (const e of entries) out[hexId(e.motion)] = { motionName: e.motionName, count: e.count };
  return out;
}

function _motionByStanceToObj(m) {
  const out = {};
  for (const [stance, inner] of m.entries()) {
    out[hexId(stance)] = _motionMapToObj(inner);
  }
  return out;
}

// Phase 11 (2026-05-26): pull server-authoritative PowerLevel /
// AccuracyLevel from the wasm `SessionHandle::playerPowerState()`
// getter. Read on-demand from summary() / snapshot() — no shared cell
// here; the wasm side already publishes both fields alongside the rest
// of `playerStats()` on every `kind=8 PlayerStatsUpdated` drain.
// Returns `{ powerLevel, accuracyLevel }` with `null` for missing
// components (the wasm getter encodes "missing" as `NaN`).
function _readServerPowerState() {
  try {
    const sh = (typeof window !== "undefined") ? window.__sessionHandle : null;
    if (!sh || typeof sh.playerPowerState !== "function") return { powerLevel: null, accuracyLevel: null };
    const arr = sh.playerPowerState();
    if (!arr || arr.length < 2) return { powerLevel: null, accuracyLevel: null };
    const p = Number(arr[0]);
    const a = Number(arr[1]);
    return {
      powerLevel: Number.isFinite(p) ? p : null,
      accuracyLevel: Number.isFinite(a) ? a : null,
    };
  } catch (_) {
    return { powerLevel: null, accuracyLevel: null };
  }
}

// Wave 9 / Phase 28 (2026-05-26): mirror of `_readServerPowerState` for
// the server's RESOLVED modifiers (`PropertyFloat::CurrentPowerMod = 23`,
// `AccuracyMod = 24`) sourced from
// `SessionHandle::playerResolvedModifiers()`. These are distinct from
// `_readServerPowerState`'s PowerLevel/AccuracyLevel (which is the raw
// slider input) — these are the server's post-resolution multiplier
// values applied to the attack roll. Same NaN→null normalization. Both
// pulls are cheap (read-on-demand, no shared cell) — the wasm side
// publishes them alongside `playerStats()` on every `kind=8
// PlayerStatsUpdated` drain.
function _readServerResolvedModifiers() {
  try {
    const sh = (typeof window !== "undefined") ? window.__sessionHandle : null;
    if (!sh || typeof sh.playerResolvedModifiers !== "function") return { currentPowerMod: null, accuracyMod: null };
    const arr = sh.playerResolvedModifiers();
    if (!arr || arr.length < 2) return { currentPowerMod: null, accuracyMod: null };
    const cpm = Number(arr[0]);
    const am = Number(arr[1]);
    return {
      currentPowerMod: Number.isFinite(cpm) ? cpm : null,
      accuracyMod: Number.isFinite(am) ? am : null,
    };
  } catch (_) {
    return { currentPowerMod: null, accuracyMod: null };
  }
}

export function attachCombat(diag) {
  // Kick the motion-name table fetch eagerly so snapshot() output is
  // humanized by the time the user inspects it. Failures don't break diag.
  try { _ensureMotionNamesLoaded(); } catch (_) {}

  const combat = {
    loaded: new Map(),        // tableId → {maneuverCount, stanceCount, loadedAt}
    failures: [],
    hits: 0,
    hitsSample: [],           // ring; recent hit tuples for spot inspection
    misses: [],               // ring; recent miss tuples (with reason)
    missCountByReason: { stance: 0, height: 0, type: 0 },
    motionHistogram: new Map(),    // motion_u32 → count (resolved motions across all stances)
    motionByStance: new Map(),     // stance_u32 → Map<motion_u32, count>
    // Wave 3 Phase 7 (2026-05-26): count aim-level motion dispatches
    // for missile attacks. Incremented from `scene3d/picking.js`'s
    // missile branch (scope="local") and `index.html`'s
    // `dispatchRemoteSwing` (scope="remote") when a ranged attacker
    // resolves through `getAimLevelForVelocity` instead of CMT. The
    // motion u32s themselves show up in `motionHistogram` once they
    // route through `setSwingMotion` → `onLookupHit` is NOT called
    // for these (the CMT path didn't resolve them); this counter is
    // the only observability for aim-level usage frequency.
    aimLevelInvocations: { local: 0, remote: 0 },
    // Wave 11 / Phase 36 (2026-05-26): count `sneakAttackPredicted`
    // event emissions per scope. Driven by an idempotent subscription
    // installed in `attachCombat` against `__pluginClient.events` —
    // see `_installSneakSubscription` below. This is a pure-JS
    // observability hook: no ACE-side correlation yet (future waves
    // can compare against actual damage events for accuracy stats).
    sneakPredictions: {
      local: 0,
      "local-missile": 0,
      "local-magic": 0,
      total: 0,
    },
    sneakSamples: [],
    maxSneakSamples: 50,
    // Wave 12 / Phase 39 (2026-05-26): sneak-attack predictor accuracy
    // measured against the server-broadcast AttackConditions bitmask.
    //
    // - `sneakConfirmations.matched`: a `damageDealt` event with the
    //   SneakAttack bit set arrived within the match window AND we
    //   found a pending prediction with the same defenderGuid (resolved
    //   from `defenderName` via entityManager). True positive.
    // - `sneakConfirmations.unmatchedServerBit`: server set the bit but
    //   no pending prediction matched. False negative (predictor missed
    //   a real sneak — or the server set the bit from a different
    //   trigger like SpellProjectile.cs:733 sneak mod).
    // - `sneakConfirmations.expiredPredictions`: prediction emitted but
    //   no matching damage event landed before the window closed. False
    //   positive (predictor said "behind" but ACE disagreed — likely
    //   client/server heading desync OR the server's per-poly rear
    //   hemisphere logic disagrees with our `isAttackerBehindDefender`).
    // - `falsePositiveRate = expiredPredictions / total predictions`.
    //
    // `pendingPredictions` is a per-(attackerGuid, defenderGuid) ring;
    // each entry is `{attackerGuid, defenderGuid, scope, ts}`. Swept
    // by `_sweepExpiredPredictions` on every damageDealt arrival and
    // on every prediction record (lazy sweep — no rAF/setInterval
    // overhead).
    sneakConfirmations: {
      matched: 0,
      unmatchedServerBit: 0,
      expiredPredictions: 0,
    },
    sneakMatchSamples: [],
    maxSneakMatchSamples: 50,
    pendingPredictions: [],
    maxPendingPredictions: 100,
    sneakMatchWindowMs: DEFAULT_SNEAK_MATCH_WINDOW_MS,
    maxFailures: DEFAULT_MAX_FAILURES,
    maxMisses: DEFAULT_MAX_MISSES,
    maxHitsSample: DEFAULT_MAX_HITS_SAMPLE,

    onLoadSucceeded(meta) {
      try {
        const m = meta || {};
        const tid = (m.tableId ?? 0) >>> 0;
        combat.loaded.set(tid, {
          tableId: hexId(tid),
          maneuverCount: (m.maneuverCount ?? 0) | 0,
          stanceCount: (m.stanceCount ?? 0) | 0,
          loadedAt: performance.now(),
        });
      } catch (_) {}
    },

    onLoadFailed(meta) {
      try {
        const m = meta || {};
        pushCapped(combat.failures, {
          tableId: hexId(m.tableId ?? 0),
          error: errStr(m.error),
          source: m.source || "unknown",
          ts: performance.now(),
        }, combat.maxFailures);
      } catch (_) {}
    },

    onLookupHit(meta) {
      try {
        const m = meta || {};
        combat.hits += 1;
        const stance = (m.stance ?? 0) >>> 0;
        const motion = (m.motion ?? 0) >>> 0;
        // motion-u32 histogram (cross-stance) — Phase 1 of CMT fixes 2026-05-26.
        combat.motionHistogram.set(motion, (combat.motionHistogram.get(motion) || 0) + 1);
        // per-stance breakdown.
        let perStance = combat.motionByStance.get(stance);
        if (!perStance) { perStance = new Map(); combat.motionByStance.set(stance, perStance); }
        perStance.set(motion, (perStance.get(motion) || 0) + 1);
        pushCapped(combat.hitsSample, {
          tableId: m.tableId != null ? hexId(m.tableId) : null,
          stance,
          attackHeight: (m.attackHeight ?? 0) | 0,
          attackType: (m.attackType ?? 0) | 0,
          motion,
          motionName: motionName(motion),
          powerLevel: Number(m.powerLevel ?? 0),
          candidates: (m.candidates ?? 1) | 0,
          // Wave 2 Phase 4 (2026-05-26): record which candidate the
          // ACE-port picker chose + the subdivision threshold it used so
          // the histogram audit can confirm both `motions[0]` (high
          // power) and `motions[1]` (low power, backhand) fire across
          // a varying powerLevel sweep instead of pinning to one slot.
          candidateIdx: (m.candidateIdx ?? 0) | 0,
          subdivision: Number(m.subdivision ?? 0.33),
          prevMotion: (m.prevMotion ?? 0) >>> 0,
          ts: performance.now(),
        }, combat.maxHitsSample);
      } catch (_) {}
    },

    onLookupMiss(meta) {
      try {
        const m = meta || {};
        const reason = m.reason || "unknown";
        if (reason in combat.missCountByReason) {
          combat.missCountByReason[reason] += 1;
        }
        pushCapped(combat.misses, {
          stance: (m.stance ?? 0) >>> 0,
          attackHeight: (m.attackHeight ?? 0) | 0,
          attackType: (m.attackType ?? 0) | 0,
          reason,
          ts: performance.now(),
        }, combat.maxMisses);
      } catch (_) {}
    },

    /**
     * Wave 3 Phase 7 — record an aim-level motion dispatch. Called
     * from `scene3d/picking.js`'s missile branch (scope="local") and
     * `index.html`'s `dispatchRemoteSwing` for ranged-stance remote
     * attackers (scope="remote"). The aim-level path bypasses the
     * CombatManeuverTable per ACE `Creature_Missile.cs::GetAimLevel`.
     *
     * @param {{ scope: "local" | "remote", motion?: number }} meta
     */
    onAimLevel(meta) {
      try {
        const m = meta || {};
        const scope = m.scope === "remote" ? "remote" : "local";
        combat.aimLevelInvocations[scope] += 1;
      } catch (_) {}
    },

    /**
     * Wave 11 / Phase 36 — record a `sneakAttackPredicted` event.
     * Subscribed against `__pluginClient.events` in `attachCombat`.
     * Emission sites live in `scene3d/picking.js` (melee + missile
     * branches, scope="local" / "local-missile") and the magic branch
     * (scope="local-magic"). Payload shape per Phase 9/16 spec:
     *   { attackerGuid, defenderGuid, attackType, scope, spellId? }
     *
     * Counter only — no ACE-side correlation this wave. Future waves
     * can compare prediction count vs actual sneak-damage events to
     * derive accuracy stats.
     *
     * @param {{ attackerGuid?: number, defenderGuid?: number,
     *           attackType?: number|null, spellId?: number|null,
     *           scope: "local"|"local-missile"|"local-magic"|string
     *         }} meta
     */
    onSneakAttackPredicted(meta) {
      try {
        const scope = meta?.scope || "unknown";
        if (scope in combat.sneakPredictions) {
          combat.sneakPredictions[scope] += 1;
        }
        combat.sneakPredictions.total += 1;
        const ts = performance.now();
        pushCapped(combat.sneakSamples, {
          scope,
          attackerGuid: (meta?.attackerGuid ?? 0) >>> 0,
          defenderGuid: (meta?.defenderGuid ?? 0) >>> 0,
          attackType: meta?.attackType ?? null,
          spellId: meta?.spellId ?? null,
          ts,
        }, combat.maxSneakSamples);
        // Wave 12 / Phase 39: append to the prediction-match ring.
        // First sweep expired entries so the ring doesn't grow without
        // bound on a low-damage soak (a prediction that never sees a
        // matching damageDealt counts as a false positive).
        _sweepExpiredPredictions();
        combat.pendingPredictions.push({
          attackerGuid: (meta?.attackerGuid ?? 0) >>> 0,
          defenderGuid: (meta?.defenderGuid ?? 0) >>> 0,
          scope,
          ts,
        });
        // Hard cap: oldest entries drop on overflow (also count as FP
        // because they couldn't be matched — same accounting as window
        // expiry). Soak protection only; in practice the window expires
        // well before the cap with realistic combat cadence.
        while (combat.pendingPredictions.length > combat.maxPendingPredictions) {
          const dropped = combat.pendingPredictions.shift();
          if (dropped) combat.sneakConfirmations.expiredPredictions += 1;
        }
      } catch (_) {}
    },

    /**
     * Wave 12 / Phase 39 — `damageDealt` event handler. Reads the
     * server-broadcast `AttackConditions` bitmask (surfaced unchanged by
     * `src/lib.rs:23601`) and, when the SneakAttack bit (0x4) is set,
     * tries to retroactively match against a pending
     * `sneakAttackPredicted` emission.
     *
     * Defender resolution: the wire event carries `defenderName` (string)
     * not GUID — we resolve via `entityManager.findGuidByName`. Multiple
     * monsters with the same name (e.g. "Drudge Slave") share a bucket
     * keyed by the oldest-still-alive GUID; for FP measurement this is
     * acceptable because the predictor itself emits the same GUID
     * `picking.js` chose (the targeted entity), and the entity registry
     * keeps that GUID alive while it's in the player's view.
     *
     * Subscribed via `_installDamageDealtSubscription`. Idempotent.
     *
     * @param {{ defenderName?: string, damage?: number,
     *           damageType?: string, healthPercent?: number,
     *           criticalHit?: boolean, attackConditions?: number|bigint
     *         }} detail
     */
    onDamageDealt(detail) {
      try {
        // attackConditions arrives as a JS number; the wire is u64 but
        // only bits 0x1..0x8 are defined today so the value fits in a
        // 53-bit double without precision loss. Bit 0x4 = SneakAttack.
        const conditionsRaw = detail?.attackConditions ?? 0;
        const conditions = typeof conditionsRaw === "bigint"
          ? Number(conditionsRaw)
          : Number(conditionsRaw);
        if (!Number.isFinite(conditions)) return;
        const hasSneakBit = (conditions & ATTACK_CONDITIONS_BIT_SNEAK_ATTACK) !== 0;
        if (!hasSneakBit) return;

        // Sweep window expiries before matching so an old prediction
        // can't masquerade as a match for a fresh damage event.
        _sweepExpiredPredictions();

        // Resolve defender name → guid. We can't match without a guid.
        // If resolution fails, count as unmatchedServerBit so the diag
        // surface still reflects the server-side sneak even if we
        // can't attribute it to a specific prediction.
        const defenderGuid = _resolveDefenderGuid(detail?.defenderName);
        if (defenderGuid === 0) {
          combat.sneakConfirmations.unmatchedServerBit += 1;
          return;
        }

        // Local player is the attacker for damageDealt (the wire event
        // is from `GameEventAttackerNotification` which is enqueued
        // against `Session.Network` — i.e. the attacker's session, see
        // `Player_Combat.cs:163`). Match on `defenderGuid` only; the
        // attackerGuid in the prediction is also the local player.
        const idx = combat.pendingPredictions.findIndex(
          (p) => (p.defenderGuid >>> 0) === (defenderGuid >>> 0),
        );
        if (idx >= 0) {
          const pred = combat.pendingPredictions.splice(idx, 1)[0];
          combat.sneakConfirmations.matched += 1;
          pushCapped(combat.sneakMatchSamples, {
            kind: "matched",
            attackerGuid: pred.attackerGuid,
            defenderGuid: pred.defenderGuid,
            defenderName: detail?.defenderName ?? null,
            scope: pred.scope,
            damage: (detail?.damage ?? 0) | 0,
            criticalHit: !!detail?.criticalHit,
            latencyMs: Math.round(performance.now() - pred.ts),
            ts: performance.now(),
          }, combat.maxSneakMatchSamples);
        } else {
          combat.sneakConfirmations.unmatchedServerBit += 1;
          pushCapped(combat.sneakMatchSamples, {
            kind: "unmatchedServerBit",
            defenderGuid: (defenderGuid >>> 0),
            defenderName: detail?.defenderName ?? null,
            damage: (detail?.damage ?? 0) | 0,
            criticalHit: !!detail?.criticalHit,
            ts: performance.now(),
          }, combat.maxSneakMatchSamples);
        }
      } catch (_) {}
    },

    /** Read-through to the runtime's cache. */
    cached() {
      try { return getCombatDiagSnapshot(); }
      catch (_) { return { tables: [] }; }
    },

    summary() {
      const cached = combat.cached();
      const power = _readServerPowerState();
      const resolved = _readServerResolvedModifiers();
      // Phase 39: sweep before computing summary so expired-prediction
      // counts are current at read time (otherwise FP rate lags the
      // window).
      _sweepExpiredPredictions();
      return {
        tablesLoaded: combat.loaded.size,
        tablesCached: cached.tables.length,
        failures: combat.failures.length,
        hits: combat.hits,
        misses: combat.misses.length,
        missByReason: { ...combat.missCountByReason },
        motionsDistinct: combat.motionHistogram.size,
        stancesWithHits: combat.motionByStance.size,
        aimLevelInvocations: { ...combat.aimLevelInvocations },
        // Phase 36: sneak-prediction emission counts per scope.
        sneakPredictions: { ...combat.sneakPredictions },
        // Phase 39: predictor accuracy vs server-broadcast SneakAttack bit.
        sneakConfirmations: { ...combat.sneakConfirmations },
        sneakFalsePositiveRate: _computeFalsePositiveRate(),
        sneakPendingPredictions: combat.pendingPredictions.length,
        // Phase 11: server-authoritative power/accuracy slider state
        // for client-vs-server desync visibility.
        serverPowerLevel: power.powerLevel,
        serverAccuracyLevel: power.accuracyLevel,
        // Phase 28: server-RESOLVED power/accuracy modifiers
        // (PropertyFloat::CurrentPowerMod / AccuracyMod) — distinct
        // from the slider input above; this is the post-resolution
        // value applied to the attack roll.
        serverCurrentPowerMod: resolved.currentPowerMod,
        serverAccuracyMod: resolved.accuracyMod,
      };
    },

    snapshot() {
      const power = _readServerPowerState();
      const resolved = _readServerResolvedModifiers();
      _sweepExpiredPredictions();
      return {
        ts: new Date().toISOString(),
        loaded: Array.from(combat.loaded.values()),
        cached: combat.cached(),
        failures: [...combat.failures],
        hits: combat.hits,
        hitsSample: [...combat.hitsSample],
        misses: [...combat.misses],
        missByReason: { ...combat.missCountByReason },
        motionHistogram: _motionMapToObj(combat.motionHistogram),
        motionByStance: _motionByStanceToObj(combat.motionByStance),
        motionNamesLoaded: _motionNames != null,
        aimLevelInvocations: { ...combat.aimLevelInvocations },
        // Phase 36: sneak-prediction emission counts per scope +
        // recent samples ring buffer for diag-time inspection.
        sneakPredictions: { ...combat.sneakPredictions },
        sneakSamples: [...combat.sneakSamples],
        // Phase 39: predictor accuracy + recent match samples (each
        // entry tagged `matched` or `unmatchedServerBit`).
        sneakConfirmations: { ...combat.sneakConfirmations },
        sneakFalsePositiveRate: _computeFalsePositiveRate(),
        sneakPendingPredictions: combat.pendingPredictions.length,
        sneakMatchWindowMs: combat.sneakMatchWindowMs,
        sneakMatchSamples: [...combat.sneakMatchSamples],
        // Phase 11: server-authoritative power/accuracy slider state
        // for client-vs-server desync visibility.
        serverPowerLevel: power.powerLevel,
        serverAccuracyLevel: power.accuracyLevel,
        // Phase 28: server-RESOLVED power/accuracy modifiers
        // (PropertyFloat::CurrentPowerMod / AccuracyMod) — distinct
        // from the slider input above; this is the post-resolution
        // value applied to the attack roll.
        serverCurrentPowerMod: resolved.currentPowerMod,
        serverAccuracyMod: resolved.accuracyMod,
      };
    },

    /**
     * Phase 39 setter for the prediction→damage match window. Public
     * so diag-time experimentation (e.g. probing how RTT affects the
     * match rate) doesn't require an edit + rebuild. Clamped to a sane
     * range so a stale console invocation can't pin the window at 0 or
     * an effective-infinity value.
     *
     * @param {number} ms
     */
    setSneakMatchWindowMs(ms) {
      const n = Number(ms);
      if (!Number.isFinite(n)) return;
      combat.sneakMatchWindowMs = Math.max(100, Math.min(30000, n | 0));
    },

    reset() {
      combat.failures.length = 0;
      combat.hits = 0;
      combat.hitsSample.length = 0;
      combat.misses.length = 0;
      combat.missCountByReason = { stance: 0, height: 0, type: 0 };
      combat.motionHistogram.clear();
      combat.motionByStance.clear();
      combat.aimLevelInvocations = { local: 0, remote: 0 };
      combat.sneakPredictions = {
        local: 0,
        "local-missile": 0,
        "local-magic": 0,
        total: 0,
      };
      combat.sneakSamples.length = 0;
      // Phase 39: clear confirmation accounting + drop in-flight
      // predictions. Subscription stays installed (idempotent contract
      // mirrors Phase 36).
      combat.sneakConfirmations = {
        matched: 0,
        unmatchedServerBit: 0,
        expiredPredictions: 0,
      };
      combat.sneakMatchSamples.length = 0;
      combat.pendingPredictions.length = 0;
      // Clear any in-flight subscription-install poll timers (they're
      // module-scope and self-clear on success/give-up, but reset()
      // should not leave a stray interval running). The bound
      // subscriptions themselves stay installed — reset() clears
      // counters, not the hookup (idempotent contract, Phase 36/39).
      if (_sneakSubPollTimer != null) {
        try { clearInterval(_sneakSubPollTimer); } catch (_) {}
        _sneakSubPollTimer = null;
      }
      if (_damageDealtSubPollTimer != null) {
        try { clearInterval(_damageDealtSubPollTimer); } catch (_) {}
        _damageDealtSubPollTimer = null;
      }
    },
  };

  diag.combat = combat;

  // Wave 11 / Phase 36 (2026-05-26): subscribe to
  // `__pluginClient.events` for `sneakAttackPredicted` emissions.
  // The plugin client is created post-login (set inside the
  // loginForm submit handler in index.html → `window.__pluginClient
  // = createClient(handle)`), but `attachCombat` runs at diag-init
  // time which can be either before or after login depending on
  // when the bootstrap finishes. Mirror sneak-hud.js's poll pattern:
  // try once eagerly, then poll on a low-rate interval until the
  // client is up. Subscription is idempotent (a guard flag prevents
  // double-binding) and survives `reset()` (reset clears counters,
  // not the hookup).
  _activeCombat = combat;
  _installSneakSubscription();
  _installDamageDealtSubscription();
}

// Subscription state lives at module scope so the guard survives
// `reset()` calls and (defensively) any re-`attachCombat` call. The
// handler dispatches into `_activeCombat` so re-attach swaps target
// without rebinding the bus (idempotent contract).
let _activeCombat = null;
let _sneakSubInstalled = false;
let _sneakSubPollTimer = null;
const _sneakSubHandler = (meta) => {
  try { _activeCombat?.onSneakAttackPredicted?.(meta); } catch (_) {}
};
function _installSneakSubscription() {
  if (_sneakSubInstalled) return;

  const tryHook = () => {
    try {
      const client = (typeof window !== "undefined") ? window.__pluginClient : null;
      if (!client?.events?.on) return false;
      client.events.on("sneakAttackPredicted", _sneakSubHandler);
      _sneakSubInstalled = true;
      return true;
    } catch (_) {
      return false;
    }
  };

  if (!tryHook()) {
    // Bound poll: if the plugin client never appears (e.g. the page is
    // opened without ever logging in), stop polling after ~30s instead
    // of spinning a 500ms interval forever.
    let ticks = 0;
    _sneakSubPollTimer = setInterval(() => {
      if (tryHook()) {
        try { clearInterval(_sneakSubPollTimer); } catch (_) {}
        _sneakSubPollTimer = null;
        return;
      }
      ticks += 1;
      if (ticks >= SUB_POLL_MAX_TICKS) {
        try { clearInterval(_sneakSubPollTimer); } catch (_) {}
        _sneakSubPollTimer = null;
        // eslint-disable-next-line no-console
        console.warn("[diag.combat] gave up waiting for __pluginClient (sneakAttackPredicted not subscribed)");
      }
    }, 500);
  }
}

// Wave 12 / Phase 39 (2026-05-26): mirror of `_installSneakSubscription`
// for the `damageDealt` event. The bus emits CustomEvent-shaped objects
// (`ev.detail` carries the JSON payload) — same convention used by
// `plugins/combat-bar.js:1467`. Install once; reset() doesn't touch the
// subscription (counters reset, hookup persists).
let _damageDealtSubInstalled = false;
let _damageDealtSubPollTimer = null;
const _damageDealtSubHandler = (ev) => {
  try { _activeCombat?.onDamageDealt?.(ev?.detail ?? {}); } catch (_) {}
};
function _installDamageDealtSubscription() {
  if (_damageDealtSubInstalled) return;

  const tryHook = () => {
    try {
      const client = (typeof window !== "undefined") ? window.__pluginClient : null;
      if (!client?.events?.on) return false;
      client.events.on("damageDealt", _damageDealtSubHandler);
      _damageDealtSubInstalled = true;
      return true;
    } catch (_) {
      return false;
    }
  };

  if (!tryHook()) {
    // Bound poll: give up after ~30s if the plugin client never shows
    // (mirror of the sneak-subscription poll's ceiling).
    let ticks = 0;
    _damageDealtSubPollTimer = setInterval(() => {
      if (tryHook()) {
        try { clearInterval(_damageDealtSubPollTimer); } catch (_) {}
        _damageDealtSubPollTimer = null;
        return;
      }
      ticks += 1;
      if (ticks >= SUB_POLL_MAX_TICKS) {
        try { clearInterval(_damageDealtSubPollTimer); } catch (_) {}
        _damageDealtSubPollTimer = null;
        // eslint-disable-next-line no-console
        console.warn("[diag.combat] gave up waiting for __pluginClient (damageDealt not subscribed)");
      }
    }, 500);
  }
}

// ---------------------------------------------------------------------
// Phase 39 helpers — kept at module scope so they're cheap to invoke
// from both the sneak handler and the damageDealt handler.
// ---------------------------------------------------------------------

// Sweep `pendingPredictions` for entries older than the match window.
// Each evicted entry counts as a false positive (predictor said the
// hit would qualify as sneak but no matching damageDealt with the
// SneakAttack bit arrived inside the window). Mutates the active
// combat state — no-op when no diag is attached.
function _sweepExpiredPredictions() {
  const c = _activeCombat;
  if (!c) return;
  const now = performance.now();
  const cutoff = now - (c.sneakMatchWindowMs || DEFAULT_SNEAK_MATCH_WINDOW_MS);
  // Predictions are appended in time order so a single front-trim
  // is sufficient. (Splice from index 0 in a loop is cheap for the
  // expected ~tens-of-entries depth; full GC every snapshot tick.)
  while (c.pendingPredictions.length > 0 && c.pendingPredictions[0].ts < cutoff) {
    c.pendingPredictions.shift();
    c.sneakConfirmations.expiredPredictions += 1;
  }
}

// Resolve a defender NAME (as carried by GameEventAttackerNotification)
// to a GUID by querying the live entity manager. Returns 0 when the
// scene isn't ready or the name doesn't have an active entity.
function _resolveDefenderGuid(name) {
  if (typeof name !== "string" || name.length === 0) return 0;
  try {
    const em = (typeof window !== "undefined")
      ? window.liveScene3d?.entityManager
      : null;
    if (!em || typeof em.findGuidByName !== "function") return 0;
    return (em.findGuidByName(name) >>> 0) || 0;
  } catch (_) {
    return 0;
  }
}

// `falsePositiveRate = expiredPredictions / total predictions`. Returns
// null when no predictions have fired yet (avoids a `0/0 = NaN` leak
// into the snapshot JSON). The denominator is the lifetime prediction
// count, not the in-flight queue depth.
function _computeFalsePositiveRate() {
  const c = _activeCombat;
  if (!c) return null;
  const total = c.sneakPredictions?.total | 0;
  if (total <= 0) return null;
  const fp = c.sneakConfirmations?.expiredPredictions | 0;
  return fp / total;
}
